def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]
    seen = [[False]*W for _ in range(H)]
    out = [row[:] for row in grid]
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and not seen[i][j]:
                color = grid[i][j]
                stack = [(i, j)]
                seen[i][j] = True
                cells = []
                while stack:
                    r, c = stack.pop()
                    cells.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] != bg:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
                rs = [r for r, c in cells]; cs = [c for r, c in cells]
                r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                h, w = r1-r0+1, c1-c0+1
                if len(cells) == 2*(h+w)-4 and h >= 3 and w >= 3:
                    fill = 7 if (h-2)*(w-2) % 2 == 1 else 2
                    for r in range(r0+1, r1):
                        for c in range(c0+1, c1):
                            out[r][c] = fill
    return out
